import random


def gini(labels):
    if not labels:
        raise ValueError('gini of no labels')
    n = len(labels)
    return 1 - sum((labels.count(c) / n) ** 2 for c in set(labels))


def best_split(X, y):
    if not X or len(X) != len(y) or any(len(row) != len(X[0]) for row in X):
        raise ValueError('need rows of equal length, one label each')
    best = None
    for f in range(len(X[0])):
        values = sorted(set(row[f] for row in X))
        for a, b in zip(values, values[1:]):
            t = (a + b) / 2
            left = [label for row, label in zip(X, y) if row[f] <= t]
            right = [label for row, label in zip(X, y) if row[f] > t]
            score = (len(left) * gini(left) + len(right) * gini(right)) / len(y)
            if best is None or score < best[2] - 1e-9:
                best = (f, t, score)
    return best


def build_tree(X, y, max_depth):
    if not X or len(X) != len(y) or any(len(row) != len(X[0]) for row in X) or max_depth < 0:
        raise ValueError('need rows of equal length, one label each, and max_depth >= 0')
    split = best_split(X, y) if max_depth > 0 and len(set(y)) > 1 else None
    if split is None:
        return {'leaf': max(sorted(set(y)), key=y.count)}
    f, t, _ = split
    left = [i for i, row in enumerate(X) if row[f] <= t]
    right = [i for i, row in enumerate(X) if row[f] > t]
    return {'feature': f, 'threshold': t,
            'left': build_tree([X[i] for i in left], [y[i] for i in left], max_depth - 1),
            'right': build_tree([X[i] for i in right], [y[i] for i in right], max_depth - 1)}


